<?php
declare(strict_types=1);require_once __DIR__.'/config/erp.php';$pdo=srnu_db();
if($_SERVER['REQUEST_METHOD']==='POST'){
 if(isset($_POST['guardar'])){$id=(int)($_POST['id']??0);$data=[epost('sku')?:null,epost('nombre'),epost('categoria'),epost('unidad','pieza'),efloat('stock'),efloat('stock_minimo'),efloat('costo_unitario'),efloat('precio_referencia')];if($data[1]!==''){if($id){$pdo->prepare('UPDATE inventario SET sku=?,nombre=?,categoria=?,unidad=?,stock=?,stock_minimo=?,costo_unitario=?,precio_referencia=?,activo=1 WHERE id=?')->execute([...$data,$id]);}else{$pdo->prepare('INSERT INTO inventario(sku,nombre,categoria,unidad,stock,stock_minimo,costo_unitario,precio_referencia,activo) VALUES(?,?,?,?,?,?,?,?,1)')->execute($data);$id=(int)$pdo->lastInsertId();if($data[4]>0)$pdo->prepare("INSERT INTO movimientos_inventario(inventario_id,tipo,cantidad,costo_unitario,referencia_tipo,notas) VALUES(?, 'Entrada inicial', ?, ?, 'Inventario','Stock inicial')")->execute([$id,$data[4],$data[6]]);}}}
 if(isset($_POST['movimiento'])){$id=(int)$_POST['id'];$tipo=epost('tipo_mov');$cant=efloat('cantidad_mov');if($id&&$cant>0){$delta=in_array($tipo,['Salida','Ajuste -'],true)?-$cant:$cant;$pdo->prepare('UPDATE inventario SET stock=GREATEST(0,stock+?) WHERE id=?')->execute([$delta,$id]);$pdo->prepare('INSERT INTO movimientos_inventario(inventario_id,tipo,cantidad,costo_unitario,referencia_tipo,notas) VALUES(?,?,?,?,?,?)')->execute([$id,$tipo,$delta,efloat('costo_mov'),'Manual',epost('notas_mov')]);}}
 if(isset($_POST['toggle']))$pdo->prepare('UPDATE inventario SET activo=IF(activo=1,0,1) WHERE id=?')->execute([(int)$_POST['id']]);
 ego('inventario.php');
}
$edit=null;if(($eid=(int)($_GET['edit']??0))){$s=$pdo->prepare('SELECT * FROM inventario WHERE id=?');$s->execute([$eid]);$edit=$s->fetch()?:null;}
$q=trim($_GET['q']??'');$sql='SELECT * FROM inventario';$args=[];if($q!==''){$sql.=' WHERE nombre LIKE ? OR sku LIKE ? OR categoria LIKE ?';$args=array_fill(0,3,'%'.$q.'%');}$sql.=' ORDER BY activo DESC,(stock<=stock_minimo) DESC,nombre';$st=$pdo->prepare($sql);$st->execute($args);$rows=$st->fetchAll();$tot=$pdo->query('SELECT COUNT(*) n,COALESCE(SUM(stock*costo_unitario),0) valor,SUM(stock<=stock_minimo AND activo=1) bajos FROM inventario WHERE activo=1')->fetch();
?><!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Inventario · SRNU</title><link rel="icon" href="favicon.png"><?=srnu_ui_head()?></head><body><?php srnu_appbar('inventario');?><main class="w"><div class="srnu-page-heading"><div><h1>Inventario</h1><p>Existencias, costos, mínimos y movimientos.</p></div><a class="btn blue" href="compras.php">Compras y proveedores</a></div><div class="kpi-grid"><div class="kpi"><small>Artículos activos</small><strong><?=number_format((int)$tot['n'])?></strong></div><div class="kpi"><small>Valor de inventario</small><strong><?=emoney($tot['valor'])?></strong></div><div class="kpi"><small>Stock bajo</small><strong><?=(int)$tot['bajos']?></strong></div><div class="kpi"><small>Servicios con receta</small><strong><?=$pdo->query('SELECT COUNT(DISTINCT catalogo_id) FROM catalogo_insumos')->fetchColumn()?></strong></div></div><section class="panel" style="padding:18px;margin-top:16px"><div class="section-title"><h3><?=$edit?'Editar artículo':'Nuevo artículo'?></h3></div><form method="post" class="erp-form cols-4"><input type="hidden" name="id" value="<?=(int)($edit['id']??0)?>"><input name="sku" placeholder="SKU" value="<?=eh($edit['sku']??'')?>"><input name="nombre" required placeholder="Nombre" value="<?=eh($edit['nombre']??'')?>"><input name="categoria" placeholder="Categoría" value="<?=eh($edit['categoria']??'')?>"><input name="unidad" placeholder="Unidad" value="<?=eh($edit['unidad']??'pieza')?>"><input type="number" step="0.001" name="stock" placeholder="Stock" value="<?=eh($edit['stock']??0)?>"><input type="number" step="0.001" name="stock_minimo" placeholder="Stock mínimo" value="<?=eh($edit['stock_minimo']??0)?>"><input type="number" step="0.01" name="costo_unitario" placeholder="Costo unitario" value="<?=eh($edit['costo_unitario']??0)?>"><input type="number" step="0.01" name="precio_referencia" placeholder="Precio referencia" value="<?=eh($edit['precio_referencia']??0)?>"><div class="toolbar full"><button class="btn blue" name="guardar" value="1">Guardar</button><?php if($edit):?><a class="btn light" href="inventario.php">Cancelar</a><?php endif;?></div></form></section><form class="toolbar" style="margin:16px 0"><input name="q" placeholder="Buscar inventario" value="<?=eh($q)?>"><button class="btn">Buscar</button><a class="btn light" href="inventario.php">Limpiar</a></form><section class="tablebox"><table><thead><tr><th>Artículo</th><th>Stock</th><th>Mínimo</th><th>Costo</th><th>Valor</th><th>Movimiento rápido</th><th>Acciones</th></tr></thead><tbody><?php foreach($rows as $r):$low=(float)$r['stock']<=(float)$r['stock_minimo'];?><tr class="<?=$low?'stock-low':''?>" style="<?=$r['activo']?'':'opacity:.5'?>"><td><b><?=eh($r['nombre'])?></b><div class="muted"><?=eh($r['sku'])?> · <?=eh($r['categoria'])?> · <?=eh($r['unidad'])?></div></td><td><b><?=number_format((float)$r['stock'],3)?></b><?=$low?' <span class="badge badge-red">BAJO</span>':''?></td><td><?=number_format((float)$r['stock_minimo'],3)?></td><td><?=emoney($r['costo_unitario'])?></td><td><?=emoney((float)$r['stock']*(float)$r['costo_unitario'])?></td><td><form method="post" class="toolbar"><input type="hidden" name="id" value="<?=$r['id']?>"><select name="tipo_mov"><option>Entrada</option><option>Salida</option><option>Ajuste +</option><option>Ajuste -</option></select><input style="width:90px" type="number" step="0.001" min="0" name="cantidad_mov" placeholder="Cant."><input style="width:100px" type="number" step="0.01" min="0" name="costo_mov" placeholder="Costo"><button class="btn" name="movimiento" value="1">Aplicar</button></form></td><td><a class="btn light" href="?edit=<?=$r['id']?>">Editar</a><a class="btn light" href="movimientos.php?id=<?=$r['id']?>">Movimientos</a><form method="post" style="display:inline"><input type="hidden" name="id" value="<?=$r['id']?>"><button class="btn <?=$r['activo']?'danger':'green'?>" name="toggle" value="1"><?=$r['activo']?'Desactivar':'Activar'?></button></form></td></tr><?php endforeach;?></tbody></table></section></main></body></html>
